import{_ as t,o as a,c as r,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Current task plan and Gantt","description":"Updated October 23, 2026 for adopted GDD v2. November 10: Cryptita Plays community beta testing. November 21: pre-final. The previous Marinduque school event is superseded.","frontmatter":{"title":"Current task plan and Gantt","description":"Updated October 23, 2026 for adopted GDD v2. November 10: Cryptita Plays community beta testing. November 21: pre-final. The previous Marinduque school event is superseded.","source":"docs/kanban-plan-draft.md","category":"Delivery & team","sourceUpdated":"2026-10-23T16:51:22+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/kanban-plan-draft.md","filePath":"content/docs/kanban-plan-draft.md"}'),o={name:"content/docs/kanban-plan-draft.md"};function s(i,e,d,c,l,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="current-task-plan-and-gantt">Current task plan and Gantt<a class="header-anchor" href="#current-task-plan-and-gantt" aria-label="Link to this section">​</a></h1><p>Updated October 23, 2026 for adopted <a href="/Chainy-Docs/content/docs/game-design.html">GDD v2</a>. <strong>November 10: Cryptita Plays community beta testing. November 21: pre-final.</strong> The previous Marinduque school event is superseded.</p><p>Use the <a href="https://owenlim225.github.io/Chainy-Docs/board/">live board</a> for editable cards, Gantt, named history and authoritative status. <a href="/Chainy-Docs/attachments/docs/backlog.json">backlog.json</a> is a publication snapshot, not a second editing surface. GitHub issues receive queued copies. The <a href="/Chainy-Docs/content/docs/archive/pre-v2-adoption-2026-10-23/docs/kanban-plan-draft.html">previous plan</a> preserves original dates, wording and local edits.</p><h2 id="delivery-gates">Delivery gates<a class="header-anchor" href="#delivery-gates" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Gate</th><th>Work and acceptance</th><th>Planning window</th></tr></thead><tbody><tr><td>Starting facts</td><td>Actual source/revision/Unity version, named Android build and SQLite contract</td><td>Oct 23–24</td></tr><tr><td>Web3 core</td><td>W01–W04: reward 12 once; lantern 8 + fee 1; balance 3; ownership/free equip; restoration; safe save/reload</td><td>Oct 25–28</td></tr><tr><td>Blockchain core</td><td>B01–B03/demo B07: same purchase, trusted checkpoint, three linked blocks, altered-record rejection and beacon restoration</td><td>Oct 29–30</td></tr><tr><td>Integration and QA</td><td>Core UI/art/copy, journal/encyclopedia, prerequisites, device/offline/profile/recovery checks</td><td>Oct 31–Nov 6</td></tr><tr><td>Candidate readiness</td><td>Go/no-go, blocker fixes, regression and beta rehearsal</td><td>Nov 7–9</td></tr><tr><td>Community beta</td><td>Tested core; confirmed arrangements and permitted evidence</td><td><strong>Nov 10</strong></td></tr><tr><td>Findings and evidence</td><td>Actual results, retested fixes and analysis</td><td>Nov 11–13</td></tr><tr><td>Manuscript</td><td>Consistent chapters, appendices and evidence package</td><td>Nov 14–16</td></tr><tr><td>Rehearsal</td><td>Demonstration, recovery drill and release freeze</td><td>Nov 17–20</td></tr><tr><td>Pre-final</td><td>Functional tested build, manuscript and required school evidence</td><td><strong>Nov 21</strong></td></tr></tbody></table><p>Internal dates are targets, not estimates of person-hours or proof of completed work. Several technical verification cards describe checks within the same shared core increment, not independent new systems. Christian must reconcile actual capacity at the first build gate; preserve QA and rehearsal rather than silently compressing them.</p><h2 id="scope-labels">Scope labels<a class="header-anchor" href="#scope-labels" aria-label="Link to this section">​</a></h2><ul><li><strong>CORE:</strong> W01–W04 and B01–B03/demo B07, contextual Quiz, compact exploration/dialogue, wallet/inventory/ledger, quest log/encyclopedia and reliable local saves.</li><li><strong>STRETCH:</strong> A01–A03 actual local classifier, only after core acceptance and capacity approval. AI guide/environment cards stay out of the core dependency path; their later dates are placeholders unless explicitly pulled forward.</li><li><strong>FULL:</strong> W05–W08, B04–B06/full B07, A04–A05, standalone Wordle/BlockMatch and their result screens.</li><li><strong>LATER SERVICE:</strong> teacher provisioning/vouchers, offline pairing/protected dashboard, multi-phone collection, upload and distribution.</li></ul><p>The board requires dates even for deferred work. November 22–December 18 on FULL/LATER/STRETCH cards is a <strong>provisional post-pre-final planning window</strong>, not a promised release. Re-estimate at the relevant gate. No deferred card is a prerequisite for core beta integration or freeze.</p><h2 id="ownership-and-status-rules">Ownership and status rules<a class="header-anchor" href="#ownership-and-status-rules" aria-label="Link to this section">​</a></h2><p>Each card has one owner: Sherwin decisions/coordination; Christian code/data/builds/integration; Luis art; Sean authored docs; Miguel UI. Preserve current individual owners and Done/In Progress states. A new requirement does not erase prior completion; acceptance of v2 does not complete a gameplay task.</p><p>Use separate role handoffs. Core chapter completion/revisit UI and later standalone mini-game result/replay UI now have distinct cards instead of duplicate titles. Five new v2 work packets cover wallet/purchase/restoration, Blockchain repair and their wallet/repair/journal UI.</p><h2 id="open-readiness-questions">Open readiness questions<a class="header-anchor" href="#open-readiness-questions" aria-label="Link to this section">​</a></h2><p>Sean records actual school requirements, the 60% calculation and whether community beta evidence satisfies the pilot-area requirement. Sherwin reconfirms Cryptita Plays participants/devices/arrangements. Christian supplies tested build/schema and capacity evidence. These are existing board actions, not implied approvals.</p><p>See <a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">acceptance</a>, <a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">implementation order</a>, <a href="/Chainy-Docs/content/docs/team-delegation.html">role guide</a> and <a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">evidence map</a>. Card counts and illustrations never establish school completion.</p></div>',1)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
